mapper.select:
select CARD_NO, PHONE, CARD_STATUS, EMPLOYEE_NAME, ID_CARD_NO, COMPANY, CENTER, DEPARTMENT, POSITION, PHOTO, CREATE_TMS, UPDATE_TMS
from ACC_SIM_EMPLOYEE_CARD
where CARD_NO = #{cardNo,jdbcType=VARCHAR}

mapper.update:
update ACC_SIM_EMPLOYEE_CARD
set CARD_STATUS = #{cardStatus,jdbcType=INTEGER}, UPDATE_TMS = SYSTIMESTAMP
where CARD_NO = #{cardNo,jdbcType=VARCHAR}

mapper.select:
select CARD_NO, PHONE, CARD_STATUS, EMPLOYEE_NAME, ID_CARD_NO, COMPANY, CENTER, DEPARTMENT, POSITION, PHOTO, CREATE_TMS, UPDATE_TMS from ACC_SIM_EMPLOYEE_CARD
and CARD_NO like '%' || #{cardNo,jdbcType=VARCHAR} || '%' and EMPLOYEE_NAME like '%' || #{employeeName,jdbcType=VARCHAR} || '%' and CARD_STATUS = #{cardStatus,jdbcType=INTEGER}
order by UPDATE_TMS desc
